#!/usr/bin/env bash
# Qtron - installer voor Linux (Kali/Debian/Ubuntu).
# Gebruik:  bash install-qtron.sh
# Installeert in ~/qtron, maakt een eigen Python-omgeving,
# en start de app automatisch (ook na herstart) op poort 8501, bereikbaar in je thuisnetwerk.
set -euo pipefail
DIR="${QTRON_DIR:-$HOME/qtron}"
OLD="$HOME/money-flow-command-center"
PORT="${QTRON_PORT:-8501}"
echo "==> Installeren in $DIR (poort $PORT)"
if ! python3 -c "import venv, ensurepip" 2>/dev/null; then
  echo "==> python3-venv ontbreekt; installeren (sudo wachtwoord kan gevraagd worden)"
  sudo apt-get update -y && sudo apt-get install -y python3-venv python3-pip
fi
mkdir -p "$DIR"
# --- geheugen, portefeuille en caches van Money Flow meenemen (eenmalig), oude dienst stoppen ---
if [ -d "$OLD/cache" ] && [ ! -d "$DIR/cache" ]; then
  echo "==> Geheugen en portefeuille overnemen uit $OLD"
  cp -a "$OLD/cache" "$DIR/cache"
fi
systemctl --user disable --now qtron.service 2>/dev/null || true
pkill -f "$OLD/.venv/bin/streamlit" 2>/dev/null || true
sed '1,/^__PAYLOAD__$/d' "$0" | base64 -d | tar -xz -C "$DIR"
python3 -m venv "$DIR/.venv"
"$DIR/.venv/bin/pip" install --quiet --upgrade pip
"$DIR/.venv/bin/pip" install --quiet -r "$DIR/requirements.txt"
cat > "$DIR/start.sh" <<START
#!/usr/bin/env bash
cd "$DIR"
exec "$DIR/.venv/bin/streamlit" run app.py --server.headless true --server.address 0.0.0.0 --server.port $PORT
START
chmod +x "$DIR/start.sh"
cat > "$DIR/collect.sh" <<COLL
#!/usr/bin/env bash
cd "$DIR"
rm -f "$DIR/cache/collector.lock"
exec "$DIR/.venv/bin/python" collector.py >> "$DIR/cache/collector.log" 2>&1
COLL
chmod +x "$DIR/collect.sh"

# --- eigen app-venster: starter + icoon in het programmamenu en op het bureaublad ---
cat > "$DIR/qtron.sh" <<LAUNCH
#!/usr/bin/env bash
# Opent Qtron als eigen venster (zonder adresbalk). Start de app eerst als die niet draait.
URL="http://localhost:$PORT"
up() { (exec 3<>/dev/tcp/127.0.0.1/$PORT) 2>/dev/null; }
if ! up; then
  systemctl --user start qtron.service 2>/dev/null || (nohup "$DIR/start.sh" > "$DIR/app.log" 2>&1 &)
  for i in \$(seq 1 80); do up && break; sleep 0.5; done
fi
for b in brave-browser brave chromium chromium-browser google-chrome google-chrome-stable microsoft-edge-stable; do
  if command -v "\$b" >/dev/null 2>&1; then
    exec "\$b" --app="\$URL" --class=Qtron --user-data-dir="$DIR/.appwindow" --no-first-run --no-default-browser-check --window-size=1700,1050
  fi
done
exec xdg-open "\$URL"
LAUNCH
chmod +x "$DIR/qtron.sh"
APPS="$HOME/.local/share/applications"
mkdir -p "$APPS"
cat > "$APPS/qtron.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=Qtron
Comment=Qtron - geldstromen, patronen, archief
Exec=$DIR/qtron.sh
Icon=$DIR/icon.svg
Terminal=false
Categories=Office;Finance;
StartupWMClass=Qtron
DESK
chmod +x "$APPS/qtron.desktop"
update-desktop-database "$APPS" 2>/dev/null || true
DESKTOP_DIR=$(xdg-user-dir DESKTOP 2>/dev/null || echo "$HOME/Desktop")
if [ -d "$DESKTOP_DIR" ]; then
  cp "$APPS/qtron.desktop" "$DESKTOP_DIR/qtron.desktop"
  chmod +x "$DESKTOP_DIR/qtron.desktop"
  gio set "$DESKTOP_DIR/qtron.desktop" metadata::trusted true 2>/dev/null || true
  gio set "$DESKTOP_DIR/qtron.desktop" metadata::xfce-exe-checksum "$(sha256sum "$DESKTOP_DIR/qtron.desktop" | awk '{print $1}')" 2>/dev/null || true
fi
IP=$(hostname -I 2>/dev/null | awk '{print $1}'); IP=${IP:-localhost}
if [ "${QTRON_NO_SERVICE:-0}" != "1" ] && command -v systemctl >/dev/null && systemctl --user show-environment >/dev/null 2>&1; then
  mkdir -p "$HOME/.config/systemd/user"
  cat > "$HOME/.config/systemd/user/qtron.service" <<UNIT
[Unit]
Description=Qtron
After=network-online.target

[Service]
ExecStart=$DIR/start.sh
Restart=on-failure
RestartSec=5

[Install]
WantedBy=default.target
UNIT
  cat > "$HOME/.config/systemd/user/qtron-collector.service" <<UNIT
[Unit]
Description=Qtron verzamelaar
After=network-online.target

[Service]
Type=oneshot
ExecStart=$DIR/collect.sh
UNIT
  cat > "$HOME/.config/systemd/user/qtron-collector.timer" <<UNIT
[Unit]
Description=Qtron verzamelaar, elke nacht na het Amerikaanse slot

[Timer]
OnCalendar=*-*-* 23:20:00
Persistent=true

[Install]
WantedBy=timers.target
UNIT
  systemctl --user daemon-reload
  systemctl --user enable qtron.service
  systemctl --user restart qtron.service
  systemctl --user enable --now qtron-collector.timer
  loginctl enable-linger "$USER" 2>/dev/null || echo "   (tip: 'sudo loginctl enable-linger $USER' laat de app draaien zonder ingelogd te zijn)"
  echo "==> Dienst 'qtron' draait; de verzamelaar loopt elke nacht om 23:20 (gemist = ingehaald bij opstarten). Beheer: systemctl --user status|restart|stop qtron"
else
  pkill -f "$DIR/.venv/bin/streamlit" 2>/dev/null || true
  sleep 1
  nohup "$DIR/start.sh" > "$DIR/app.log" 2>&1 &
  echo "==> Gestart op de achtergrond (log: $DIR/app.log). Opnieuw starten: $DIR/start.sh"
fi
echo
echo "KLAAR. Start de app met het icoon 'Qtron' (bureaublad of programmamenu), of: $DIR/qtron.sh"
echo "       In een browser:        http://localhost:$PORT"
echo "       Op je telefoon (wifi): http://$IP:$PORT"
exit 0
__PAYLOAD__
H4sIAAAAAAAAA+RaW3PbRpbOM39FDzwZgwkJgZREy5TpGoqibE1ESRbpxCqVltMEmiQiEI00AEm0
